CREATE TABLE IF NOT EXISTS mc_public_appreciations (seq INTEGER PRIMARY KEY AUTOINCREMENT, donor_id TEXT NOT NULL UNIQUE, first_verified INTEGER, hidden INTEGER NOT NULL DEFAULT 0);
CREATE TRIGGER IF NOT EXISTS mc_apprec_verify_insert AFTER INSERT ON donors WHEN upper(trim(NEW.verification_status))='VERIFIED' BEGIN INSERT OR IGNORE INTO mc_public_appreciations(donor_id,first_verified) VALUES(NEW.id,unixepoch()); END;
CREATE TRIGGER IF NOT EXISTS mc_apprec_verify_update AFTER UPDATE OF verification_status ON donors WHEN upper(trim(NEW.verification_status))='VERIFIED' AND upper(trim(coalesce(OLD.verification_status,'')))!='VERIFIED' BEGIN INSERT OR IGNORE INTO mc_public_appreciations(donor_id,first_verified) VALUES(NEW.id,unixepoch()); END;
INSERT OR IGNORE INTO mc_public_appreciations(donor_id,first_verified) SELECT d.id,(SELECT min(happened_at) FROM donor_events e WHERE e.donor_id=d.id AND e.action='admin_verified_sheet') FROM donors d WHERE upper(trim(d.verification_status))='VERIFIED' ORDER BY d.created_at,d.id;
